## 6. Backend Skeleton (Node + Express)

```js
// server.js
import express from 'express';
import crypto from 'crypto';
import { Pool } from 'pg';

const app = express();
app.use(express.json());
const db = new Pool({ connectionString: process.env.DATABASE_URL });

// Anonymous auth
app.post('/auth/anonymous', async (req, res) => {
  const deviceId = req.body.device_id;
  const handle = `shadow_${crypto.randomInt(1000, 9999)}`;
  const { rows } = await db.query(
    `INSERT INTO users (id, handle) VALUES (gen_random_uuid(), $1) RETURNING *`,
    [handle]
  );
  res.json({ user: rows[0], token: signToken(rows[0].id) });
});

// Send a roast
app.post('/roasts', async (req, res) => {
  const { target_handle, body } = req.body;
  const senderId = req.user.id;

  const target = await db.query(
    `SELECT id FROM users WHERE handle = $1`, [target_handle]
  );
  if (!target.rows.length) return res.status(404).json({ error: 'no target' });

  // One-way hash: sender can never be unmasked
  const senderHash = crypto
    .createHash('sha256')
    .update(senderId + target.rows[0].id)
    .digest('hex');

  await db.query(
    `INSERT INTO roasts (id, target_id, sender_hash, body)
     VALUES (gen_random_uuid(), $1, $2, $3)`,
    [target.rows[0].id, senderHash, body]
  );

  await db.query(
    `UPDATE users SET roast_score = roast_score + 1 WHERE id = $1`,
    [target.rows[0].id]
  );

  res.json({ message: 'Delivered. No consequences.' });
});

// Clapback
app.post('/roasts/:id/clapback', async (req, res) => {
  const { body } = req.body;
  await db.query(
    `INSERT INTO clapbacks (id, roast_id, body)
     VALUES (gen_random_uuid(), $1, $2)`,
    [req.params.id, body]
  );
  await db.query(
    `UPDATE users SET resilience = resilience + 1
     WHERE id = (SELECT target_id FROM roasts WHERE id = $1)`,
    [req.params.id]
  );
  res.json({ message: 'Clapped back.' });
});

app.listen(3000);
```

