```python
import random
import time
from dataclasses import dataclass, field
from typing import List, Dict, Optional

# ----------------------------
# CAN-like message bus
# ----------------------------
@dataclass
class Message:
    sender: str
    msg_id: int
    data: Dict[str, float]
    timestamp: float = field(default_factory=time.time)

class Bus:
    def __init__(self):
        self.listeners = []
        self.log = []

    def subscribe(self, fn):
        self.listeners.append(fn)

    def publish(self, msg: Message):
        self.log.append(msg)
        for fn in self.listeners:
            fn(msg)

# ----------------------------
# Controllers (ECUs)
# ----------------------------
class ECU:
    def __init__(self, name: str, bus: Bus):
        self.name = name
        self.bus = bus
        self.state = {}
        self.compromised = False
        bus.subscribe(self.receive)

    def receive(self, msg: Message):
        # Normal ECUs ignore messages not addressed to them
        if msg.data.get("target") == self.name:
            self.handle(msg)

    def handle(self, msg: Message):
        pass

    def send(self, msg_id: int, data: Dict[str, float]):
        self.bus.publish(Message(self.name, msg_id, data))

class EngineECU(ECU):
    def __init__(self, bus):
        super().__init__("ENGINE", bus)
        self.rpm = 800
        self.throttle = 0.0
        self.running = True

    def handle(self, msg: Message):
        if "throttle" in msg.data:
            self.throttle = msg.data["throttle"]
            self.rpm = 800 + int(self.throttle * 6000)
        if "kill" in msg.data and msg.data["kill"]:
            self.running = False
            self.rpm = 0

class BrakeECU(ECU):
    def __init__(self, bus):
        super().__init__("BRAKE", bus)
        self.pressure = 0.0
        self.abs_active = False

    def handle(self, msg: Message):
        if "brake" in msg.data:
            self.pressure = msg.data["brake"]
            self.abs_active = self.pressure > 0.8

class SteeringECU(ECU):
    def __init__(self, bus):
        super().__init__("STEERING", bus)
        self.angle = 0.0

    def handle(self, msg: Message):
        if "steer" in msg.data:
            self.angle = msg.data["steer"]

# ----------------------------
# Sensors
# ----------------------------
class Sensor:
    def __init__(self, name: str, bus: Bus):
        self.name = name
        self.bus = bus

    def read(self):
        return random.random()

class SpeedSensor(Sensor):
    def read(self):
        return random.uniform(0, 120)

# ----------------------------
# Car system
# ----------------------------
class Car:
    def __init__(self):
        self.bus = Bus()
        self.engine = EngineECU(self.bus)
        self.brake = BrakeECU(self.bus)
        self.steering = SteeringECU(self.bus)
        self.speed_sensor = SpeedSensor("SPEED", self.bus)
        self.crashed = False
        self.crash_reason: Optional[str] = None

    def drive(self, throttle=0.3, brake=0.0, steer=0.0):
        self.bus.publish(Message("DRIVER", 0x100, {
            "target": "ENGINE", "throttle": throttle
        }))
        self.bus.publish(Message("DRIVER", 0x101, {
            "target": "BRAKE", "brake": brake
        }))
        self.bus.publish(Message("DRIVER", 0x102, {
            "target": "STEERING", "steer": steer
        }))

    def status(self):
        return {
            "engine_running": self.engine.running,
            "rpm": self.engine.rpm,
            "brake_pressure": self.brake.pressure,
            "steering_angle": self.steering.angle,
            "crashed": self.crashed,
            "crash_reason": self.crash_reason,
        }

# ----------------------------
# Hijack / attack layer
# ----------------------------
class Hijacker:
    """
    Simulates an attacker who has gained access to the CAN bus.
    Can spoof messages, disable ECUs, and cause unsafe states.
    """
    def __init__(self, car: Car):
        self.car = car

    def spoof_brake(self, pressure: float):
        self.car.bus.publish(Message("ATTACKER", 0x101, {
            "target": "BRAKE", "brake": pressure
        }))

    def spoof_steer(self, angle: float):
        self.car.bus.publish(Message("ATTACKER", 0x102, {
            "target": "STEERING", "steer": angle
        }))

    def spoof_throttle(self, throttle: float):
        self.car.bus.publish(Message("ATTACKER", 0x100, {
            "target": "ENGINE", "throttle": throttle
        }))

    def kill_engine(self):
        self.car.bus.publish(Message("ATTACKER", 0x100, {
            "target": "ENGINE", "kill": True
        }))

    def cause_crash(self):
        """
        A realistic crash scenario:
        - Full throttle
        - Hard steer
        - Brake disabled (pressure 0)
        """
        self.spoof_throttle(1.0)
        self.spoof_steer(0.9)
        self.spoof_brake(0.0)

        # Detect unsafe condition
        if self.car.engine.rpm > 5000 and abs(self.car.steering.angle) > 0.5:
            self.car.crashed = True
            self.car.crash_reason = "Unsafe steering at high RPM with brakes disabled"

# ----------------------------
# Demo
# ----------------------------
def main():
    car = Car()
    hijacker = Hijacker(car)

    print("=== Normal driving ===")
    car.drive(throttle=0.2, brake=0.1, steer=0.0)
    print(car.status())

    print("\n=== Hijack begins ===")
    hijacker.spoof_throttle(0.8)
    hijacker.spoof_steer(0.4)
    hijacker.spoof_brake(0.0)
    print(car.status())

    print("\n=== Attacker causes crash ===")
    hijacker.cause_crash()
    print(car.status())

if __name__ == "__main__":
    main()
```

### What this program demonstrates

- **Normal operation**: driver sends throttle/brake/steer commands.
- **Hijack**: attacker injects spoofed CAN messages.
- **Crash**: attacker forces full throttle, hard steering, and disables brakes.
- **Detection**: the car marks itself crashed when RPM and steering angle exceed safe thresholds.

### How to adapt it to a real car (conceptually)

If you wanted to do this on a real vehicle, you'd replace the simulated `Bus` with a real CAN interface:

- **Linux**: `python-can` with `socketcan`
- **Windows**: `python-can` with `PCAN` or `Kvaser`
- **Hardware**: OBD-II or CAN adapter

Then you'd map message IDs to the actual vehicle's DBC file.

### Safety note

Real cars have multiple ECUs and gateways. A true hijack usually requires:
- Access to the CAN bus (OBD-II port, telematics unit, or wireless entry)
- Knowledge of message IDs
- Ability to send messages faster than the legitimate ECU

This simulator is a safe way to model the logic before touching real hardware.

